import streamlit as st
import pandas as pd
from fpdf import FPDF
import re
import pyAesCrypt
import requests
import os
import base64

# ====================== CONFIG ======================
st.set_page_config(page_title="SVCE STTP Certificate Generator", layout="centered")

# ====================== COUNTERS ======================
def update_visit_count():
    count_file = "counter.txt"
    if not os.path.exists(count_file):
        with open(count_file, "w") as f:
            f.write("0")
    with open(count_file, "r") as f:
        count = int(f.read())
    if "counted" not in st.session_state:
        count += 1
        with open(count_file, "w") as f:
            f.write(str(count))
        st.session_state.counted = True
    return count

def update_download_count():
    count_file = "downloads.txt"
    if not os.path.exists(count_file):
        with open(count_file, "w") as f:
            f.write("0")
    with open(count_file, "r") as f:
        count = int(f.read())
    count += 1
    with open(count_file, "w") as f:
        f.write(str(count))
    return count

def get_download_count():
    count_file = "downloads.txt"
    if not os.path.exists(count_file):
        return 0
    with open(count_file, "r") as f:
        return int(f.read())

visit_count = update_visit_count()
download_total = get_download_count()

# ====================== HEADER ======================
st.title("SVCE_CSE: STTP Certificate Generator")
st.markdown(f"<div style='text-align:right; color:gray;'>👁️ Day Visits: {visit_count}</div>", unsafe_allow_html=True)
st.markdown(f"<div style='text-align:right; color:gray;'>📥 Day Downloads: {download_total}</div>", unsafe_allow_html=True)

# ====================== LOAD & DECRYPT EXCEL ======================

buffer_size = 64 * 1024

try:
    # Get password from Streamlit secrets
    password = st.secrets["excel_password"]

    encrypted_url = (
        "https://raw.githubusercontent.com/"
        "eraghu21/STTPAUG31-SEP04-Intelligent-Vision-Systems-/"
        "main/registrations.xlsx.aes"
    )

    enc_file = "registrations.xlsx.aes"
    dec_file = "registrations.xlsx"

    # ------------------------------------------------
    # STEP 1: Download encrypted Excel
    # ------------------------------------------------
    resp = requests.get(encrypted_url, timeout=30)

    st.write("Download status:", resp.status_code)
    st.write("Downloaded bytes:", len(resp.content))

    if resp.status_code != 200:
        st.error(
            f"❌ GitHub download failed. HTTP Status: {resp.status_code}"
        )
        st.stop()

    if len(resp.content) == 0:
        st.error("❌ Downloaded encrypted file is empty.")
        st.stop()

    with open(enc_file, "wb") as f:
        f.write(resp.content)

    # ------------------------------------------------
    # STEP 2: Decrypt AES file
    # ------------------------------------------------
    pyAesCrypt.decryptFile(
        enc_file,
        dec_file,
        password,
        buffer_size
    )

    st.success("✅ Excel file decrypted successfully.")

    # ------------------------------------------------
    # STEP 3: Read Excel
    # ------------------------------------------------
    df = pd.read_excel(dec_file)

    st.success(f"✅ Participant data loaded: {len(df)} records")

    # ------------------------------------------------
    # STEP 4: Clean up temporary files
    # ------------------------------------------------
    if os.path.exists(enc_file):
        os.remove(enc_file)

    if os.path.exists(dec_file):
        os.remove(dec_file)

except KeyError:
    st.error(
        "❌ 'excel_password' is missing from Streamlit Secrets."
    )
    st.info(
        "Add excel_password to Streamlit Cloud → Settings → Secrets."
    )
    st.stop()

except pyAesCrypt.AESDecryptionError:
    st.error(
        "❌ AES decryption failed."
    )
    st.info(
        "Check whether the excel_password in Streamlit Secrets "
        "matches the password used to encrypt registrations.xlsx.aes."
    )
    st.stop()

except Exception as e:
    st.error(
        f"❌ Error loading participant data: "
        f"{type(e).__name__}"
    )
    st.error(f"Details: {str(e)}")
    st.stop()
# ====================== CLEAN COLUMN NAMES ======================
df.columns = df.columns.str.strip().str.lower()
# ====================== EMBEDDED CERTIFICATE BACKGROUND ======================
certificate_base64 =""""""
def save_certificate_background():
    img_bytes = base64.b64decode(certificate_base64)
    file_path = "certificate_bg.jpeg"
    with open(file_path, "wb") as f:
        f.write(img_bytes)
    return file_path

bg_image_path = save_certificate_background()

# ====================== EMAIL INPUT ======================
email_input = st.text_input("📧 Enter your registered Email")

def is_valid_email(email):
    pattern = r'^[\w\.-]+@[\w\.-]+\.\w+$'
    return re.match(pattern, email)

# ====================== GENERATE CERTIFICATE ======================
if st.button("Generate Certificate"):
    if not is_valid_email(email_input):
        st.warning("⚠️ Please enter a valid email address.")
    else:
        match = df[df['email'].str.strip().str.lower() == email_input.strip().lower()]
        if not match.empty:
            row = match.iloc[0]
            attendance = row['attendance']
            if attendance >= 3:
                name = row['name']
                designation_raw = row['designation'].strip().lower()
                college = row['college_name']

                if "assistant" in designation_raw:
                    designation = "Assistant Professor"
                elif "associate" in designation_raw:
                    designation = "Associate Professor"
                elif "professor" in designation_raw:
                    designation = "Professor"
                else:
                    designation = row['designation'].strip().title()

                pdf = FPDF(orientation='L', unit='mm', format='A4')
                pdf.add_page()
                pdf.image(bg_image_path, x=0, y=0, w=297, h=210)
                pdf.add_font("AlexBrush", "", "AlexBrush-Regular.ttf", uni=True)

                pdf.ln(65)
                pdf.set_font("AlexBrush", '', 54)
                pdf.set_x(10)
                pdf.set_text_color(212, 175, 55)
                pdf.cell(0, 12, txt=name.strip().title(), ln=True, align='C')

                pdf.ln(2)
                pdf.set_font("AlexBrush", size=22)
                pdf.set_x(15)
                pdf.set_text_color(0, 0, 0)
                pdf.cell(0, 10, designation.strip().title(), ln=True, align='C')

                pdf.ln(1)
                pdf.set_font("AlexBrush", size=22)
                pdf.cell(0, 10, txt=college.strip().title(), ln=True, align='C')

                cert_filename = f"certificate_{name.strip().replace(' ', '_')}.pdf"
                pdf.output(cert_filename)

                with open(cert_filename, "rb") as f:
                    st.success("✅ Certificate generated successfully!")
                    st.download_button("📥 Download Certificate", f, file_name=cert_filename, mime="application/pdf")
                    update_download_count()

                os.remove(cert_filename)
            else:
                st.warning("⚠️ Your attendance is less than required.")
        else:
            st.error("❌ Email not found in the registration records.")
